// Mirrors Assets/World/LundunWorld.json (schema 1.1). Plain data, loaded with JsonUtility.
// Never edit the JSON by hand: it is generated by Tools/WorldData/export.py.
using System;
using System.Collections.Generic;

[Serializable] public class LwPoint { public float x, z; }

[Serializable] public class LwHeights
{
    public float ground, roadSurface, pavementTop, waterSurface, riverBed, embankmentWallTop, bridgeDeck;
}

[Serializable] public class LwBounds
{
    public float groundMinX, groundMaxX, groundMinZ, groundMaxZ, wallMinX, wallMaxX, wallMinZ, wallMaxZ;
}

[Serializable] public class LwCamera { public float farClip, fogStart, fogEnd; }

[Serializable] public class LwRoadClass
{
    public string name;
    public float width, pavement, verge, centralReservation;
    public int lanesPerDirection;
}

[Serializable] public class LwRiver
{
    public float width, wallThickness;
    public LwPoint[] centreline;
}

[Serializable] public class LwRoad
{
    public string id, name, roadClass;
    public float width, lengthM;
    public LwPoint[] points;
    public string[] junctions;
    public float[] junctionChainage;
}

[Serializable] public class LwBridge
{
    public string id, roadId, name;
    public LwPoint northEnd, southEnd, waterEntry, waterExit;
    public float width, deckY, deckThickness, parapetHeight;
}

[Serializable] public class LwLeg { public string road, toward; }

[Serializable] public class LwJunction
{
    public string id;
    public float x, z;
    public int arms;
    public string[] roads;
    public LwLeg[] legs;
}

[Serializable] public class LwPoly
{
    public string id, name;
    public LwPoint[] polygon;
}

[Serializable] public class LwPoi
{
    public string id, name, kind;
    public float x, z, yaw;
}

[Serializable] public class LwSpawn
{
    public string id, note;
    public float x, z, yaw;
}

[Serializable] public class LwExistingStreet
{
    public string prefab, replacesRoad;
    public float centreX, centreZ, sizeX, sizeZ, replacesFromX, replacesToX;
}

[Serializable] public class LundunWorldData
{
    public string schemaVersion;
    public LwHeights heights;
    public LwBounds worldBounds;
    public LwCamera camera;
    public LwRoadClass[] roadClasses;
    public LwRiver river;
    public LwRoad[] roads;
    public LwBridge[] bridges;
    public LwJunction[] junctions;
    public LwPoly[] districts;
    public LwPoly[] parks;
    public LwPoi[] pois;
    public LwSpawn[] spawns;
    public LwExistingStreet existingStreet;
    /// E0: the map expansions (LundunExpansion.json), kept apart so the base city is built exactly as before.
    [NonSerialized] public LundunExpansionData expansion;
}

/// E0: the map expansions, Assets/World/LundunExpansion.json. Read after the base world and never mixed into it:
/// the generator builds the base city exactly as it always has, then each expansion area with its own random seeds.
/// worldBounds is the bigger playable area: the ground, the hedge round the edge and the map picture grow to it.
[Serializable] public class LundunExpansionData
{
    public string schemaVersion;
    public LwBounds worldBounds;
    public LwRoadClass[] roadClasses = new LwRoadClass[0];     // E1: any road classes the expansions add
    public LwRoad[] roads = new LwRoad[0];
    public LwJunction[] junctions = new LwJunction[0];
    public LwPoly[] districts = new LwPoly[0];
    public LwPoly[] parks = new LwPoly[0];
    public LwPoi[] pois = new LwPoi[0];
}

/// E0: reading the world files the same way everywhere (the editor menus and the game).
public static class LundunWorldFiles
{
    public const string BasePath = "Assets/World/LundunWorld.json";
    public const string ExpansionPath = "Assets/World/LundunExpansion.json";

    /// For building the city: the base world with the expansion's bounds; everything else in the expansion
    /// waits in data.expansion for the expansion builders.
    public static LundunWorldData Parse(string baseJson, string expansionJson)
    {
        LundunWorldData d = UnityEngine.JsonUtility.FromJson<LundunWorldData>(baseJson);
        if (d == null || string.IsNullOrEmpty(expansionJson)) return d;
        LundunExpansionData x = UnityEngine.JsonUtility.FromJson<LundunExpansionData>(expansionJson);
        if (x == null) return d;
        d.expansion = x;
        if (x.worldBounds != null && x.worldBounds.wallMaxX > x.worldBounds.wallMinX) d.worldBounds = x.worldBounds;
        return d;
    }

    /// For the game (map labels, the GPS road graph, places): the base world with the expansion's roads,
    /// junctions, districts, parks and places added on the end.
    /// E1: where an expansion road joins a base road the two are tied together: a junction the expansion lists
    /// under a base junction's id adds its legs to that junction, and a new junction on a base road (one whose
    /// roads include that base road) is added to the base road's own list, so routes run straight through.
    public static LundunWorldData ParseCombined(string baseJson, string expansionJson)
    {
        return Combine(Parse(baseJson, expansionJson));
    }

    /// E1: the base world (with its expansion attached) turned into one world: see ParseCombined.
    public static LundunWorldData Combine(LundunWorldData d)
    {
        if (d == null || d.expansion == null) return d;
        LundunExpansionData x = d.expansion;
        d.roadClasses = Join(d.roadClasses, x.roadClasses);
        Dictionary<string, int> baseJ = new Dictionary<string, int>();
        for (int i = 0; i < d.junctions.Length; i++) baseJ[d.junctions[i].id] = i;
        Dictionary<string, int> baseR = new Dictionary<string, int>();
        for (int i = 0; i < d.roads.Length; i++) baseR[d.roads[i].id] = i;
        List<LwJunction> extra = new List<LwJunction>();
        foreach (LwJunction j in x.junctions)
        {
            int bi;
            if (baseJ.TryGetValue(j.id, out bi))
            {
                // an existing junction gains the expansion's legs (copied, so the base data stays as it was)
                LwJunction b = d.junctions[bi];
                List<string> rs = new List<string>(b.roads); foreach (string r in j.roads) if (!rs.Contains(r)) rs.Add(r);
                List<LwLeg> legs = new List<LwLeg>(b.legs); legs.AddRange(j.legs);
                d.junctions[bi] = new LwJunction { id = b.id, x = b.x, z = b.z, arms = legs.Count, roads = rs.ToArray(), legs = legs.ToArray() };
                continue;
            }
            extra.Add(j);
            foreach (string rid in j.roads)
            {
                int ri;
                if (!baseR.TryGetValue(rid, out ri)) continue;
                // a new junction on a base road: add it to that road's list at its distance along
                LwRoad r = d.roads[ri];
                float ch = Chainage(r.points, j.x, j.z);
                List<string> js = new List<string>(r.junctions); List<float> jc = new List<float>(r.junctionChainage);
                int at = 0; while (at < jc.Count && jc[at] < ch) at++;
                js.Insert(at, j.id); jc.Insert(at, ch);
                d.roads[ri] = new LwRoad { id = r.id, name = r.name, roadClass = r.roadClass, width = r.width, lengthM = r.lengthM, points = r.points, junctions = js.ToArray(), junctionChainage = jc.ToArray() };
            }
        }
        d.roads = Join(d.roads, x.roads);
        d.junctions = Join(d.junctions, extra.ToArray());
        d.districts = Join(d.districts, x.districts);
        d.parks = Join(d.parks, x.parks);
        d.pois = Join(d.pois, x.pois);
        return d;
    }

    /// Distance along a polyline to the point nearest (x, z).
    public static float Chainage(LwPoint[] pts, float x, float z)
    {
        double best = double.MaxValue, at = 0, run = 0;
        for (int i = 0; i + 1 < pts.Length; i++)
        {
            double ax = pts[i].x, az = pts[i].z, dx = pts[i + 1].x - ax, dz = pts[i + 1].z - az, l2 = dx * dx + dz * dz, L = Math.Sqrt(l2);
            double t = l2 < 1e-9 ? 0 : Math.Max(0, Math.Min(1, ((x - ax) * dx + (z - az) * dz) / l2));
            double ex = ax + dx * t - x, ez = az + dz * t - z, d = ex * ex + ez * ez;
            if (d < best) { best = d; at = run + L * t; }
            run += L;
        }
        return (float)at;
    }

    static T[] Join<T>(T[] a, T[] b)
    {
        if (b == null || b.Length == 0) return a;
        if (a == null || a.Length == 0) return b;
        T[] r = new T[a.Length + b.Length];
        Array.Copy(a, r, a.Length); Array.Copy(b, 0, r, a.Length, b.Length);
        return r;
    }
}
